MIROIR["53:2"] = {
  reference: "53:2",
  theme: ["prophète", "égarement", "guidance"],
  emotion: "Confiance, vérification",
  difficulty: "débutant",
  relatedNames: ["Al-Hadi", "As-Siraj"],
  mirrorVersion: `« Votre compagnon ne s'est pas égaré et n'a pas été induit en erreur. » Le miroir défend le Prophète. « Ma dalla sahibukum wa ma ghawa » — votre compagnon ne s'est pas égaré et n'a pas été induit en erreur. L'accusation d'égarement est fausse. Le miroir m'invite à vérifier mes propres sources de guidance.`,
  reflection: `Le Prophète était sur le droit chemin. Ses accusateurs étaient les égarés.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Ma dalla sahibukum wa ma ghawa » — votre compagnon ne s'est pas égaré et n'a pas été induit en erreur." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Qui j'accuse d'égarement ? Et moi, suis-je sur le droit chemin ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "L'accusation d'égarement vient souvent des égarés." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La vérité est un chemin droit. Le mensonge est un labyrinthe." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui suit le Prophète suit le chemin sans égarement." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "Dans l'ombre de ce verset se cache ma part d'ombre : ce que je projette sur les autres, ce que je refuse de reconnaître en moi. L'ombre est le miroir de mes refus." }
  ],
  munajat: `Ya Hadi, Tu es le Guide. Fais que je suive Ton Prophète sans dévier. Ne permets pas que je sois parmi les égarés.`
};

