MIROIR["9:69"] = {
  reference: "9:69",
  theme: ["histoire", "châtiment", "mémoire"],
  emotion: "Lucidité, mise en garde",
  difficulty: "intermédiaire",
  relatedNames: ["Al-Qasas", "Al-Muta'allim"],
  mirrorVersion: `« Comme ceux qui vous ont précédés et qui étaient plus forts que vous. » Le miroir me montre l'histoire répétitive. « Ka-alladhina min qablikum » — comme ceux qui vous ont précédés. Les peuples passés étaient plus forts mais ont été punis. L'histoire enseigne. Le miroir m'interroge : est-ce que j'apprends de l'histoire ?`,
  reflection: `L'histoire est un enseignement. Les peuples passés ont été punis pour leur hypocrisie.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Ka-alladhina min qablikum kanu ashadda minkum quwwatan » — comme ceux qui vous ont précédés et qui étaient plus forts que vous." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Est-ce que j'apprends de l'histoire ? Ou est-ce que je répète les mêmes erreurs ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "La force ne protège pas du châtiment divin." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "L'histoire est remplie de leçons pour ceux qui réfléchissent." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui apprend de l'histoire ne répète pas les erreurs." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "Dans l'ombre de cette révélation, je découvre mes propres contradictions. Ce que le verset dévoile de la vérité divine, il le reflète aussi sur mes propres ténèbres. L'ombre m'invite à l'honnêteté radicale." }
  ],
  munajat: `Ya Rabb, fais que j'apprenne de l'histoire. Ne permets pas que je répète les erreurs des peuples passés. Donne-moi la sagesse de l'histoire.`
};

MIROIR["9:70"] = {
  reference: "9:70",
  theme: ["histoire", "prophètes", "châtiment"],
  emotion: "Lucidité, responsabilité",
  difficulty: "débutant",
  relatedNames: ["An-Nabi", "Al-Muballigh"],
  mirrorVersion: `« Est-ce que ne leur est pas parvenue l'histoire de ceux qui les ont précédés ? » Le miroir me montre l'ignorance volontaire. « A-lam ya'tihim naba'u alladhina min qablihim » — est-ce que ne leur est pas parvenue l'histoire ? L'histoire est connue mais ignorée. Le miroir m'interroge : est-ce que j'ignore volontairement les enseignements de l'histoire ?`,
  reflection: `L'histoire des prophètes et des peuples est connue. L'ignorer est une responsabilité.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« A-lam ya'tihim naba'u alladhina min qablihim qawmi Nuhin wa 'Adin wa Thamud » — est-ce que ne leur est pas parvenue l'histoire de ceux qui les ont précédés : le peuple de Noé, des 'Ad et des Thamud ?" },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Est-ce que j'ignore volontairement les enseignements de l'histoire ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "L'ignorance volontaire est une faute." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Les prophètes ont été envoyés à tous les peuples." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui connaît l'histoire est responsable." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "L'ombre de ce verset me révèle ce que je refuse de voir en moi : mes attachements cachés, mes résistances silencieuses, les parties de mon âme que je garde dans l'obscurité. L'ombre n'est pas l'ennemie — elle est ce qui attend d'être éclairé." }
  ],
  munajat: `Ya Rabb, fais que je connaisse l'histoire des prophètes et des peuples. Donne-moi la responsabilité d'apprendre. Ne permets pas que j'ignore volontairement.`
};

