// ============================================
// SURAH 29 (AL-ANKABUT) - MISSING VERSES
// ============================================

MIROIR["29:29"] = {
  reference: "29:29",
  theme: ["lot", "péché", "avertissement"],
  emotion: "Gravité, tristesse",
  difficulty: "débutant",
  relatedNames: ["Al-Nadhir", "Al-Hakam"],
  mirrorVersion: `« Vous vous approchez des mâles, vous coupez les chemins et vous commettez le blâmable dans vos assemblées. » Le miroir me montre les péchés du peuple de Lot. Ils se sont égarés dans leurs désirs, ont coupé les chemins, commis le blâmable. La décadence morale complète. Le miroir m'interroge : quels péchés mon peuple considère-t-il normaux ?`,
  reflection: `Les péchés deviennent normaux quand la société les accepte. L'avertissement de Lot reste actuel.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Innakum la ta'tuna al-rijala wa taqta'una al-sabila wa ta'tuna fi nadikumu al-munkar » — Vous vous approchez des mâles, vous coupez les chemins et vous commettez le blâmable dans vos assemblées." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Quels péchés mon peuple normalise-t-il ? Est-ce que je m'y oppose ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "L'acceptation sociale du péché ne change pas sa nature." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "L'histoire des civilisations montre que la décadence morale précède la chute." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui s'oppose au blâmable préserve son âme." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "L'ombre portée par ce verset me montre ce que je fuis. Chaque vérité divine a son ombre humaine — les questions que je n'ose pas poser, les doutes que je cache, les peurs que je nie. L'ombre demande courage." }
  ],
  munajat: `Ya Hakam, Ton jugement est vérité. Fais que je ne normalise jamais le péché. Donne-moi le courage de m'opposer au blâmable.`
};

MIROIR["29:30"] = {
  reference: "29:30",
  theme: ["prière", "protection", "corruption"],
  emotion: "Supplication, crainte",
  difficulty: "débutant",
  relatedNames: ["Al-Nasir", "Al-Muhaymin"],
  mirrorVersion: `« Seigneur ! Aide-moi contre ce peuple corrupteur. » Le miroir me montre la prière contre la corruption. Lot ne pouvait pas changer son peuple seul — il a demandé l'aide d'Allah. Face à la corruption généralisée, la prière est l'arme. Le miroir m'interroge : est-ce que je prie contre la corruption qui m'entoure ?`,
  reflection: `Face à la corruption, la prière est puissante. Allah peut changer ce que nous ne pouvons pas.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Rabbi inzurni 'ala al-qawmi al-mufsidin » — Seigneur ! Aide-moi contre ce peuple corrupteur." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Est-ce que je prie contre la corruption ? Ou est-ce que je m'y résigne ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "La résignation face au mal est une complicité." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La corruption attire le châtiment. L'opposition attire la protection." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui prie contre la corruption est entendu." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "Dans l'ombre de ce verset se cache ma part d'ombre : ce que je projette sur les autres, ce que je refuse de reconnaître en moi. L'ombre est le miroir de mes refus." }
  ],
  munajat: `Ya Nasir, aide-moi contre la corruption qui m'entoure. Ne laisse pas mon cœur s'y résigner. Donne-moi la force de m'y opposer par la prière.`
};

MIROIR["29:37"] = {
  reference: "29:37",
  theme: ["miracle", "incrédulité", "châtiment"],
  emotion: "Tristesse, avertissement",
  difficulty: "débutant",
  relatedNames: ["Al-Mu'jizah", "Al-Qadir"],
  mirrorVersion: `« Ils le traitèrent de menteur, alors le séisme les saisit, et le lendemain matin, ils gisaient dans leurs demeures. » Le miroir me montre la conséquence de l'incrédulité. Le miracle est rejeté, le séisme vient. En une nuit, tout est fini. Le refus de croire a un prix. Le miroir m'interroge : combien de signes est-ce que je rejette ?`,
  reflection: `Le rejet des signes attire le châtiment. La terre elle-même peut devenir instrument de justice.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Fakadhdhabuhu fa akhadhat-humu al-rajfatu fa asbahu fi darihim jathimim » — Ils le traitèrent de menteur, alors le séisme les saisit, et le lendemain matin, ils gisaient dans leurs demeures." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Combien de signes est-ce que je rejette ? Quels avertissements ignore-je ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Le signe rejeté devient la preuve contre le rejeteur." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La terre tremble pour ceux qui la troublent par leur incrédulité." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui accepte les signes les voit se multiplier." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "Ce que ce verset révèle dans la lumière, l'ombre le cache dans mon cœur : les vérités que je connais mais ne vis pas, les appels que j'entends mais ignore. L'ombre est mon examen de conscience." }
  ],
  munajat: `Ya Qadir, ne laisse pas mon cœur rejeter Tes signes. Ouvre mes yeux aux avertissements. Garde-moi de l'incrédulité qui attire le châtiment.`
};

// ============================================
// SURAH 21 (AL-ANBIYA) - EXPANSION
// ============================================

MIROIR["21:2"] = {
  reference: "21:2",
  theme: ["révélation", "distraction", "cœur"],
  emotion: "Vigilance, attention",
  difficulty: "débutant",
  relatedNames: ["Al-Tanzil", "Al-Mudhakkir"],
  mirrorVersion: `« Quand leur arrive un nouveau rappel de leur Seigneur, ils l'écoutent en se divertissant. » Le miroir me montre la distraction face à la révélation. Le Coran arrive, mais ils l'écoutent comme un divertissement. Pas comme une guidance — comme un spectacle. Le miroir m'interroge : comment est-ce que j'écoute le Coran ?`,
  reflection: `Écouter le Coran en se divertissant est le refuser. Le cœur doit être présent.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Ma ya'tihim min dhikrin min rabbihim muhdathin illa istama'uhu wa hum yal'abun » — Quand leur arrive un nouveau rappel de leur Seigneur, ils l'écoutent en se divertissant." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Comment est-ce que j'écoute le Coran ? Comme divertissement ou comme guidance ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Le Coran-entertainment est une contradiction." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La Parole de Dieu mérite plus que l'attention distraite." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui écoute le Coran avec le cœur présent est transformé." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "Ce que ce verset révèle dans la lumière, l'ombre le cache dans mon cœur : les vérités que je connais mais ne vis pas, les appels que j'entends mais ignore. L'ombre est mon examen de conscience." }
  ],
  munajat: `Ya Mudhakkir, Ton rappel n'est pas un divertissement. Fais que je l'écoute avec le cœur présent. Ne laisse pas ma distraction me priver de Ta guidance.`
};

