MIROIR["27:2"] = {
  reference: "27:2",
  theme: ["guidance", "annonce", "croyants"],
  emotion: "Espérance, certitude",
  difficulty: "débutant",
  relatedNames: ["Al-Huda", "Al-Bushra"],
  mirrorVersion: `« Une guidance et une bonne nouvelle pour les croyants. » Le miroir me montre le destin du Coran. Il est guidance et bonne nouvelle — pour les croyants. Le même livre est avertissement pour les uns, bonne nouvelle pour les autres. Le miroir m'interroge : qu'est-ce que le Coran est pour moi ?`,
  reflection: `Le Coran est ce que le cœur en fait. Pour le croyant, il est bonne nouvelle.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Hudan wa bushra li al-mu'minin » — Une guidance et une bonne nouvelle pour les croyants." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Qu'est-ce que le Coran est pour moi ? Guidance et bonne nouvelle ou avertissement ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Le même message a deux effets selon la réception." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La lumière illumine ceux qui ouvrent les yeux." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui reçoit le Coran avec foi reçoit la bonne nouvelle." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "Derrière la lumière de ce verset, l'ombre me murmure mes résistances. Ce que je comprends intellectuellement mais que je refuse d'incarner. L'ombre est le lieu de ma transformation non encore accomplie." }
  ],
  munajat: `Ya Huda, fais que Ton Coran soit pour moi guidance et bonne nouvelle. Ouvre mon cœur à la recevoir. Ne laisse pas ma réception être fermée.`
};

MIROIR["27:3"] = {
  reference: "27:3",
  theme: ["prière", "aumône", "certitude"],
  emotion: "Engagement, confiance",
  difficulty: "débutant",
  relatedNames: ["Al-Muqim", "Al-Mu'ti"],
  mirrorVersion: `« Ceux qui accomplissent la prière, s'acquittent de l'aumône et croient avec certitude en l'au-delà. » Le miroir me montre les signes du croyant. La prière, l'aumône, la certitude en l'au-delà. Ces trois piliers définissent la foi. Le miroir m'interroge : ces trois piliers sont-ils présents dans ma vie ?`,
  reflection: `La foi se voit dans la pratique. Les piliers sont interconnectés.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Alladhina yuqimuna al-salata wa yu'tuna al-zakata wa hum bi al-akhirati hum yuqinun » — Ceux qui accomplissent la prière, s'acquittent de l'aumône et croient avec certitude en l'au-delà." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Ces trois piliers sont-ils présents dans ma vie ? La prière, l'aumône, la certitude ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "La foi sans pratique est morte. La pratique sans certitude est vide." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La foi est un tout. Chaque pilier soutient les autres." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui établit les trois piliers construit une foi solide." },
    { label: "L'Ombre", ar: "الظل", color: "#64748b", text: "L'ombre de ce verset cache un trésor : la partie de moi qui n'a pas encore été touchée par la révélation. Ce qui reste dans l'ombre attend son heure. La patience de l'ombre est la patience de Dieu envers mes zones d'ombre." }
  ],
  munajat: `Ya Muqim, fais que j'accomplisse la prière. Fais que je donne l'aumône. Fais que je croie en l'au-delà avec certitude. Établis ces trois piliers dans ma vie.`
};

